// validation.ts: merged because both bodies looked identical
export const isValidCode = (v: string) => /^[A-Za-z0-9-]{3,30}$/.test(v);
// Widened for coupons, so usernames now accept hyphens too

// cart.ts: the free-shipping rule, updated to 75...
export const freeShipping = (subtotal: number) => subtotal >= 75;

// banner.ts: ...and the same rule again, in a shape no detector flags
export const amountToFreeShipping = (subtotal: number) =>
  Math.max(0, 50 - subtotal);

// Two rules owned by different teams: free to diverge
export const isValidUsername = (v: string) => /^[A-Za-z0-9]{3,20}$/.test(v);
export const isValidCoupon = (v: string) => /^[A-Za-z0-9-]{3,30}$/.test(v);

// pricing.ts: one business fact, one authoritative home
export const FREE_SHIPPING_MIN = 75;

export const freeShipping = (subtotal: number) =>
  subtotal >= FREE_SHIPPING_MIN;

export const amountToFreeShipping = (subtotal: number) =>
  Math.max(0, FREE_SHIPPING_MIN - subtotal);
